#!/usr/bin/env python3
import argparse,json
from pathlib import Path
p=argparse.ArgumentParser();p.add_argument('results',type=Path);p.add_argument('--control',type=Path);a=p.parse_args();base=Path(__file__).resolve().parent
startup=json.loads((a.results/'startup-summary.json').read_text());load=json.loads((a.results/'load-summary.json').read_text());env=json.loads((a.results/'environment.json').read_text());prov=json.loads((base/'build-provenance.json').read_text())
labels={'standalone':'Modern standalone','spring':'Modern Spring','legacy':'Legacy Spring','quarkus':'Modern Quarkus','micronaut':'Modern Micronaut (Jackson 2.16.1)'}
lines=['# Matched Linux native-image results','',f'Completed batch: `{a.results.name}`. Thirty fresh native processes and five fixed-warmup load samples per accepted variant.','', '| Native executable | HTTP ready (s) | Business ready (s) | Business RSS (MiB) | Settled RSS (MiB) | Executable (MiB) |','|---|---:|---:|---:|---:|---:|']
for v,s in startup.items():
 val=lambda key:s[key]['median']
 lines.append(f"| {labels[v]} | {val('web_ready_s'):.3f} | {val('business_ready_s'):.3f} | {val('business_ready_rss_mib'):.1f} | {val('settled_rss_mib'):.1f} | {env['executables'][v]['bytes']/1048576:.1f} |")
lines+=['','All table values except executable size are medians. Business ready includes the first successful nonempty Merchant query and E expression evaluation. HTTP readiness is the exact version JSON; it does not establish a connected pool.','', '| Native executable | First read (ms) | First write to 49 (ms) | Next write to 48 (ms) | Warm read req/s | Warm write req/s |','|---|---:|---:|---:|---:|---:|']
for v,s in startup.items():
 l=load[v];lines.append(f"| {labels[v]} | {s['first_read_ms']['median']:.1f} | {s['first_write_49_ms']['median']:.1f} | {s['first_write_48_ms']['median']:.1f} | {l['read_rps']['median']:.1f} | {l['write_rps']['median']:.1f} |")
lines+=['','The bounded load is 400 reads at concurrency four and 40 alternating writes at concurrency one, after 200 reads and 20 warmup writes. HTTP/client scheduling and database work are included; these rates are not maximum throughput.','', '## Build observations','', '| Executable | Configured build elapsed | Compiler peak RSS (MiB) | Result |','|---|---:|---:|---|']
for v in labels:
 info=prov['builds'][v].get('build-configured.log',{})
 lines.append(f"| {labels[v]} | {info.get('elapsed','—')} | {int(info.get('peak_rss_kib',0))/1024:.1f} | {'Success' if info.get('exit_status')=='0' else 'See retained diagnostics'} |")
lines+=['','Builds used Oracle GraalVM 21.0.12+7.1, GCC 14.2.0, compatibility instructions, optimization level 2, four compilation threads and an 8 GiB compiler heap. They were serial. Agent training/contract checks overlapped some builds; these are shared-machine observations, not a controlled build-speed ranking.','', '## JVM comparison and scope','', 'Use the retained six-way JVM batch for legacy Spring, modern Spring, standalone classpath and Quarkus. The native standalone executable is one closed program; it does not preserve JPMS/classpath as two runtime loading modes. Native and JVM both accept -Xms128m/-Xmx512m, but native Serial GC and JVM default GC have different physical-memory behavior. OS caches were not cleared; the CPU governor and other original server services were not changed.']
if a.control:
 c=json.loads((a.control/'startup-summary.json').read_text())['micronaut'];l=json.loads((a.control/'load-summary.json').read_text())['micronaut']
 lines+=['',f"Micronaut's matched Jackson 2.16.1 JVM control is `{a.control.name}`: HTTP ready {c['web_ready_s']['median']:.3f}s, business ready {c['business_ready_s']['median']:.3f}s, business RSS {c['business_ready_rss_mib']['median']:.1f}MiB, warm reads {l['read_rps']['median']:.1f}/s and writes {l['write_rps']['median']:.1f}/s. Its native dependencies exactly match this control. The original six-way JVM Micronaut used Jackson 2.22.3 and remains separate."]
lines+=['','## Initial attempts and integration changes','','Standalone initially compiled but failed during Hikari initialization; the observed JDBC field-updater/resource metadata fixed this path. Spring initially failed to instantiate the XML-configured ConsoleAppender; tracing-agent metadata fixed that logging path. Quarkus initially rejected absent optional Hikari metrics types under global strict linkage; the configured build limits strict linkage to io.quarkus/io.teaql and enables service loading for the manual JDBC pool. Micronaut 4.3.14 referenced a Jackson naming strategy removed in 2.22; the native-compatible profile aligns Jackson 2.16.1. The unconfigured legacy attempt was superseded after analysis. Its subsequent image compiled but failed the first real SQL query: Hutool package scanning discovered no SQL expression parsers. A native-only adapter bootstrap explicitly registers the exact 17 shipped parser implementations, with separate instances per repository, and restores WARN after legacy AOT logging. The old runtime and controller operations remain unchanged; this required adaptation is part of the reported deployment stack.','','The traced standalone contract recorded 61 reflection entries, zero TeaQL package types and zero application package types. The AOT legacy trace recorded 1,092 entries, including 80 TeaQL types and 94 application package types (including configuration/repositories/adapters). These counts describe observed reflection in this workload, not the compiler’s total registrations or arbitrary application coverage. Modern Spring still traces adapter/container reflection.','','Modern adapter source commit 075990f and legacy native-bootstrap commit fb1fb9c use the same controller/operation source as JVM commit 176a323. Spring Boot adds parameter metadata to compiled application classes; their bytes differ, while the generated domain and published TeaQL artifacts are unchanged. Local/unreleased generator changes remain required. The hours=47 rejection is the adapter fixture guard, not a framework authorization or forced-failure rollback test. Full original-service migration, schema parity, Android, encrypted reference/ID JSON, field masking and database-failure rollback remain outside this measurement.','','## Evidence','',f'- [Startup CSV]({a.results.name}/startup.csv) and [summary]({a.results.name}/startup-summary.json).',f'- [Load CSV]({a.results.name}/load.csv) and [summary]({a.results.name}/load-summary.json).',f'- [Executable identity and environment]({a.results.name}/environment.json).','- [Build provenance](build-provenance.json), actual compiler logs and observed metadata.','- [Pre/post business contract](contract-verification.json), [collector](collect_native.py), [launcher](start-native.sh), [build commands](build-native.sh).']
(base/'results.md').write_text('\n'.join(lines)+'\n')
print(base/'results.md')

# Preserve ranking annotations when regenerating the report.
import importlib.util
_rank_path = Path(__file__).resolve().parent.parent / "rank_tables.py"
_rank_spec = importlib.util.spec_from_file_location("rank_tables", _rank_path)
_rank_module = importlib.util.module_from_spec(_rank_spec)
_rank_spec.loader.exec_module(_rank_module)
_rank_module.annotate_file(Path(__file__).resolve().parent / "results.md")
